#include <vector>
#include <cmath>

using namespace std;

class Solution {
public:
    int minSpeedOnTime(vector<int>& dist, double hour) {
        int lo = 1, hi = 1e7, ans = -1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            double time = 0;
            for (int i = 0; i < dist.size(); ++i)
                time += i + 1 == dist.size() ? (double)dist[i] / mid : ceil((double)dist[i] / mid);
            if (time <= hour) {
                ans = mid;
                hi = mid - 1;
            } else lo = mid + 1;
        }
        return ans;
    }
};
